import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _differs(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null or b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_store = inputs['DIM_STORE'].copy()
    stg = inputs['STG_STORE_FULL'].copy()
    batch = inputs['BATCH_CONTROL'].copy()

    # exactly one batch row
    b = batch['batch_date'].iloc[0]

    # distinct store/region/format combos from the full snapshot
    S = stg.drop_duplicates(subset=['store_id', 'region', 'format']).reset_index(drop=True)

    # map store_id -> list of row indices that are currently "current"
    current_by_store = {}
    if 'is_current' in dim_store.columns:
        current_mask = dim_store['is_current'] == 1
        for idx, row in dim_store[current_mask].iterrows():
            current_by_store.setdefault(row['store_id'], []).append(idx)

    new_rows = []
    rows_to_close = set()
    s_store_ids = set()

    for _, s in S.iterrows():
        store_id = s['store_id']
        s_store_ids.add(store_id)
        idxs = current_by_store.get(store_id)

        if idxs:
            # representative current row for attribute comparison
            c = dim_store.loc[idxs[0]]
            if _differs(c['region'], s['region']) or _differs(c['format'], s['format']):
                for idx in idxs:
                    rows_to_close.add(idx)
                new_rows.append({
                    'store_id': store_id,
                    'region': s['region'],
                    'format': s['format'],
                    'eff_start_date': b,
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })
            # else: attributes unchanged -> no-op, no new version
        else:
            # brand-new store or reopened store: always gets a new version
            new_rows.append({
                'store_id': store_id,
                'region': s['region'],
                'format': s['format'],
                'eff_start_date': b,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })

    # close current rows for stores no longer present in the snapshot
    for store_id, idxs in current_by_store.items():
        if store_id not in s_store_ids:
            for idx in idxs:
                rows_to_close.add(idx)

    for idx in rows_to_close:
        dim_store.at[idx, 'eff_end_date'] = b
        dim_store.at[idx, 'is_current'] = 0

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=dim_store.columns)
        result = pd.concat([dim_store, new_df], ignore_index=True)
    else:
        result = dim_store

    result = result.reset_index(drop=True)

    return {'dim_store_out': result}
